# T-3437: the swap+restart runner that fleet-deploy-binary.sh pushes to a hub's
# host. Generated here (sourced) so a fixture can emit and inspect it without
# ever running it against a live hub.
#   write_deploy_runner <out-file> <staged-binary-path> <expected-sha256>
write_deploy_runner() {
    local out="$1" DST="$2" EXPECTED_SHA="$3" lib
    lib="$(dirname "${BASH_SOURCE[0]}")/hub-runtime-dir.sh"
    [ -r "$lib" ] || { echo "write_deploy_runner: $lib missing" >&2; return 1; }
    cat > "$out" <<EOF
#!/bin/bash
# Auto-generated by fleet-deploy-binary.sh
exec >> /tmp/fleet-deploy.log 2>&1
echo "===== \$(date) deploy start ====="
NEW="$DST"
EXPECTED_SHA="$EXPECTED_SHA"
ACTUAL=\$(sha256sum "\$NEW" | awk '{print \$1}')
[ "\$ACTUAL" = "\$EXPECTED_SHA" ] || { echo "ABORT: sha mismatch"; exit 1; }

# T-3449: the kernel reports a replaced binary as "<path> (deleted)". That is not a file
# name: strip it (repeatedly) before using it as a path.
real_path() { local e="\$1"; while [ "\${e% (deleted)}" != "\$e" ]; do e="\${e% (deleted)}"; done; printf '%s' "\$e"; }
# T-3449: find hubs by what they ARE (a "hub start" process whose binary is termlink), not by
# the phrase "termlink hub start" in the command line: a hub launched from an odd path
# ("/usr/local/bin/termlink (deleted) hub start") does not contain that phrase and was missed.
hub_pids() {
  local p e
  for p in \$(pgrep -f '[h]ub start'); do
    e=\$(real_path "\$(readlink "/proc/\$p/exe" 2>/dev/null)")
    case "\${e##*/}" in termlink|"termlink "*) echo "\$p" ;; esac
  done
}
any_hub() { [ -n "\$(hub_pids)" ]; }

# Locate the running hub binary's path via /proc/PID/exe
PID=\$(hub_pids | head -1)
[ -z "\$PID" ] && { echo "no running hub — staging only"; exit 0; }
TARGET=\$(real_path "\$(readlink "/proc/\$PID/exe")")
echo "running hub PID=\$PID at \$TARGET"
# T-3323: capture the RUNNING hub's runtime dir and arguments BEFORE the kill.
# Relaunching with the exec session's env (or the old ~/.termlink/runtime
# fallback) could move the hub to a fresh runtime dir, where it regenerates its
# secret and cert and every client loses auth (PL-021).
# T-3437: a hub started WITHOUT TERMLINK_RUNTIME_DIR resolved its dir by the
# binary's default chain (discovery.rs: XDG_RUNTIME_DIR/termlink, then
# TMPDIR/termlink-<uid>, then /tmp/termlink-<uid>). Reading only the explicit
# variable moved .132's hub to a fresh dir on 2026-10-13 (new cert + secret).
# Resolve exactly as the binary did, from the hub's OWN environment and uid, and
# accept the dir only if its hub.pid names this hub. Otherwise refuse before
# anything is stopped.
# @@HUB_RUNTIME_DIR_LIB@@
RUN_RT=\$(hub_runtime_dir "\$PID") || { echo "ABORT: cannot confirm the running hub's runtime dir; refusing to stop or relaunch it (T-3437)"; exit 1; }
CERT_SHA_BEFORE=\$(sha256sum "\$RUN_RT/hub.cert.pem" 2>/dev/null | cut -d' ' -f1)
mapfile -d '' RUN_ARGV < "/proc/\$PID/cmdline" 2>/dev/null || RUN_ARGV=()
RUN_ARGS=("\${RUN_ARGV[@]:1}")
[ "\${#RUN_ARGS[@]}" -ge 2 ] && [ "\${RUN_ARGS[0]}" = hub ] || RUN_ARGS=(hub start --tcp 0.0.0.0:9100)
TCP_PORT=""
for ((ai = 0; ai < \${#RUN_ARGS[@]}; ai++)); do
  [ "\${RUN_ARGS[ai]}" = --tcp ] && TCP_PORT="\${RUN_ARGS[ai+1]##*:}"
done
echo "running hub runtime_dir=\$RUN_RT (confirmed by hub.pid) args=\${RUN_ARGS[*]} cert_sha=\${CERT_SHA_BEFORE:0:16}"

# Backup
BAK="\$TARGET.\$(date +%s).bak"
cp "\$TARGET" "\$BAK" 2>/dev/null || { echo "WARN: backup failed"; BAK=""; }

# T-3447: swap BEFORE the stop. On Linux the running hub keeps its unlinked inode, so
# from here on ANY restarter (this runner or the host's own watchdog) starts the new
# binary. On .121 (2026-10-17) a watchdog relaunched the old file inside the old
# stop-wait-swap window and the deploy left the old version serving.
SWAPPED=0
if rm -f "\$TARGET" 2>/dev/null && cp "\$NEW" "\$TARGET" 2>/dev/null && chmod +x "\$TARGET"; then
  SWAPPED=1; echo "swap done before the stop (a restarter now starts the new binary)"
else
  echo "swap before the stop failed (busy file?); falling back to stop-wait-swap"
  if [ ! -x "\$TARGET" ]; then
    [ -n "\$BAK" ] && cp "\$BAK" "\$TARGET" && chmod +x "\$TARGET" || { echo "ABORT: \$TARGET missing and no backup to restore"; exit 1; }
    echo "restored \$TARGET from \$BAK"
  fi
fi

# Detach
sleep 3

# Kill, wait for exit
kill "\$PID"
for i in \$(seq 1 15); do
  any_hub || { echo "hub exited after \${i}s"; break; }
  sleep 1
done
any_hub && { for p in \$(hub_pids); do kill -9 "\$p"; done; sleep 2; }

if [ "\$SWAPPED" = 0 ]; then
  # NTFS DrvFs: 5s wait for file-lock release
  sleep 5
  # rm-then-cp avoids "Text file busy" on NTFS DrvFs
  rm -f "\$TARGET" || { echo "ABORT: rm failed"; exit 1; }
  cp "\$NEW" "\$TARGET" || { echo "ABORT: cp failed"; exit 1; }
  chmod +x "\$TARGET"
  echo "swap done after the stop"
fi

# Relaunch detached, matching launcher pattern
sleep 1
HOME_DIR=\$(getent passwd "\$(id -un)" | cut -d: -f6)
cd "\$HOME_DIR"
# T-3437: never a fallback dir; RUN_RT was confirmed above.
RUNTIME="\$RUN_RT"
echo "relaunching with TERMLINK_RUNTIME_DIR=\$RUNTIME"
TERMLINK_RUNTIME_DIR="\$RUNTIME" \
  setsid nohup "\$TARGET" "\${RUN_ARGS[@]}" \
  >> /tmp/termlink-hub.log 2>&1 < /dev/null &
NEW_PID=\$!
echo "relaunched hub PID=\$NEW_PID"

sleep 5
if ! any_hub; then
  echo "\$(date) hub did NOT come back"
  echo "===== deploy done ====="; exit 1
fi
# T-3447: every running hub must run the NEW file. A hub some other restarter started from
# the old file shows its exe as another path or "<path> (deleted)"; stop it once, relaunch.
stale_hubs() {
  local p e
  for p in \$(hub_pids); do
    e=\$(readlink "/proc/\$p/exe")
    [ "\$e" = "\$TARGET" ] || echo "\$p:\$e"
  done
}
STALE=\$(stale_hubs)
if [ -n "\$STALE" ]; then
  echo "STALE: hub running another file: \$STALE — replacing it once"
  while IFS= read -r s; do kill "\${s%%:*}"; done <<< "\$STALE"  # an exe may read "<path> (deleted)"
  for i in \$(seq 1 15); do [ -z "\$(stale_hubs)" ] && break; sleep 1; done
  if ! any_hub; then
    TERMLINK_RUNTIME_DIR="\$RUNTIME" setsid nohup "\$TARGET" "\${RUN_ARGS[@]}" >> /tmp/termlink-hub.log 2>&1 < /dev/null &
    echo "relaunched hub PID=\$!"
  fi
  sleep 5
  STALE=\$(stale_hubs)
  if [ -n "\$STALE" ] || ! any_hub; then
    echo "STALE after one replacement: \${STALE:-no hub running}"; echo "===== deploy done ====="; exit 1
  fi
fi
echo "\$(date) hub UP version=\$("\$TARGET" --version 2>&1 | head -1)"
# T-3437: the relaunched hub must serve the SAME cert from the SAME dir.
CERT_SHA_AFTER=\$(sha256sum "\$RUNTIME/hub.cert.pem" 2>/dev/null | cut -d' ' -f1)
if [ -n "\$CERT_SHA_BEFORE" ] && [ "\$CERT_SHA_AFTER" != "\$CERT_SHA_BEFORE" ]; then
  echo "CERT CHANGED: \$RUNTIME/hub.cert.pem differs after the relaunch (PL-021 rotation)"; echo "===== deploy done ====="; exit 1
fi
if [ -n "\$TCP_PORT" ]; then
  FP_FILE=\$(TERMLINK_RUNTIME_DIR="\$RUNTIME" "\$TARGET" hub fingerprint 2>/dev/null | grep -o 'sha256:[0-9a-f]*' | head -1)
  FP_PORT=\$(timeout 10 "\$TARGET" hub probe "127.0.0.1:\$TCP_PORT" 2>/dev/null | grep -o 'sha256:[0-9a-f]*' | head -1)
  if [ -z "\$FP_PORT" ] || [ "\$FP_PORT" != "\$FP_FILE" ]; then
    echo "CERT MISMATCH: port \$TCP_PORT presents \${FP_PORT:-nothing}, \$RUNTIME holds \${FP_FILE:-nothing} (the hub is not serving its own dir)"; echo "===== deploy done ====="; exit 1
  fi
  echo "cert unchanged: port \$TCP_PORT presents \$FP_PORT from \$RUNTIME"
fi
# T-3449: an earlier runner could leave a file literally named "<TARGET> (deleted)" and run a
# hub from it. Once no process runs from it, remove it.
STRAY="\$TARGET (deleted)"
if [ -f "\$STRAY" ]; then
  in_use=0
  for p in \$(hub_pids); do [ "\$(readlink "/proc/\$p/exe")" = "\$STRAY" ] && in_use=1; done
  if [ "\$in_use" = 0 ]; then rm -f -- "\$STRAY" && echo "removed stray \$STRAY"; else echo "WARN: \$STRAY still in use"; fi
fi
echo "===== deploy done ====="
EOF
    # Embed the runtime-dir resolver verbatim at its marker (the runner runs on
    # another host, so it cannot source a file from this checkout).
    sed -i "/^# @@HUB_RUNTIME_DIR_LIB@@\$/r $lib" "$out"
    grep -q '^hub_runtime_dir() {' "$out" || { echo "write_deploy_runner: resolver not embedded" >&2; return 1; }
}
